     1→-- 기존 함수 모두 삭제 (파라미터 수 또는 리턴 타입이 달라 CREATE OR REPLACE 불가)
     2→DROP FUNCTION IF EXISTS submit_battle_record(UUID, TEXT, INTEGER);
     3→DROP FUNCTION IF EXISTS submit_battle_record(UUID, TEXT, INTEGER, BOOLEAN);
     4→
     5→-- 친선전 전적 컬럼 추가
     6→ALTER TABLE public.battle_records
     7→  ADD COLUMN IF NOT EXISTS friendly_wins        INTEGER NOT NULL DEFAULT 0,
     8→  ADD COLUMN IF NOT EXISTS friendly_losses      INTEGER NOT NULL DEFAULT 0,
     9→  ADD COLUMN IF NOT EXISTS friendly_disconnects INTEGER NOT NULL DEFAULT 0;
    10→
    11→-- submit_battle_record 함수 업데이트: p_is_ranked 파라미터 추가
    12→-- 컬럼명 모호성 방지: 현재값을 변수로 먼저 읽고 UPDATE에서 변수만 사용
    13→CREATE OR REPLACE FUNCTION submit_battle_record(
    14→  p_user_id     UUID,
    15→  p_result      TEXT,
    16→  p_point_delta INTEGER,
    17→  p_is_ranked   BOOLEAN DEFAULT TRUE
    18→)
    19→RETURNS TABLE(
    20→  out_rating_points        INTEGER,
    21→  out_wins                 INTEGER,
    22→  out_losses               INTEGER,
    23→  out_disconnects          INTEGER,
    24→  out_friendly_wins        INTEGER,
    25→  out_friendly_losses      INTEGER,
    26→  out_friendly_disconnects INTEGER,
    27→  out_rank                 BIGINT
    28→)
    29→LANGUAGE plpgsql SECURITY DEFINER AS $$
    30→DECLARE
    31→  v_rp   INT;
    32→  v_w    INT;
    33→  v_l    INT;
    34→  v_d    INT;
    35→  v_fw   INT;
    36→  v_fl   INT;
    37→  v_fd   INT;
    38→  v_rank BIGINT;
    39→BEGIN
    40→  -- 1. 신규 유저 레코드 생성 (기존 유저는 무시)
    41→  INSERT INTO public.battle_records (user_id) VALUES (p_user_id)
    42→  ON CONFLICT (user_id) DO NOTHING;
    43→
    44→  -- 2. 현재 값을 변수로 읽기 (UPDATE 우변의 모호성 방지)
    45→  SELECT br.rating_points, br.wins, br.losses, br.disconnects,
    46→         br.friendly_wins, br.friendly_losses, br.friendly_disconnects
    47→    INTO v_rp, v_w, v_l, v_d, v_fw, v_fl, v_fd
    48→    FROM public.battle_records br WHERE br.user_id = p_user_id;
    49→
    50→  v_rp := COALESCE(v_rp, 0);
    51→  v_w  := COALESCE(v_w,  0);
    52→  v_l  := COALESCE(v_l,  0);
    53→  v_d  := COALESCE(v_d,  0);
    54→  v_fw := COALESCE(v_fw, 0);
    55→  v_fl := COALESCE(v_fl, 0);
    56→  v_fd := COALESCE(v_fd, 0);
    57→
    58→  -- 3. 변수만 사용해 UPDATE (컬럼명 모호성 없음)
    59→  IF p_is_ranked THEN
    60→    v_rp := GREATEST(0, v_rp + p_point_delta);
    61→    v_w  := v_w  + CASE WHEN p_result = 'win'        THEN 1 ELSE 0 END;
    62→    v_l  := v_l  + CASE WHEN p_result = 'lose'       THEN 1 ELSE 0 END;
    63→    v_d  := v_d  + CASE WHEN p_result = 'disconnect' THEN 1 ELSE 0 END;
    64→
    65→    UPDATE public.battle_records SET
    66→      rating_points = v_rp,
    67→      wins          = v_w,
    68→      losses        = v_l,
    69→      disconnects   = v_d,
    70→      updated_at    = NOW()
    71→    WHERE user_id = p_user_id;
    72→  ELSE
    73→    v_fw := v_fw + CASE WHEN p_result = 'win'        THEN 1 ELSE 0 END;
    74→    v_fl := v_fl + CASE WHEN p_result = 'lose'       THEN 1 ELSE 0 END;
    75→    v_fd := v_fd + CASE WHEN p_result = 'disconnect' THEN 1 ELSE 0 END;
    76→
    77→    UPDATE public.battle_records SET
    78→      friendly_wins        = v_fw,
    79→      friendly_losses      = v_fl,
    80→      friendly_disconnects = v_fd,
    81→      updated_at           = NOW()
    82→    WHERE user_id = p_user_id;
    83→  END IF;
    84→
    85→  -- 4. 랭크 계산
    86→  SELECT COUNT(*) + 1 INTO v_rank
    87→    FROM public.battle_records br2 WHERE br2.rating_points > v_rp;
    88→
    89→  RETURN QUERY SELECT v_rp, v_w, v_l, v_d, v_fw, v_fl, v_fd, v_rank;
    90→END; $$;
    91→
