await supabaseAdmin
  .from('profiles')
  .update({ initials: userName })
  .eq('id', user.id);

// 기존 점수 조회
const { data: existing } = await supabaseAdmin
  .from('leaderboard')
  .select('score')
  .eq('user_id', user.id)
  .eq('difficulty', difficulty)
  .single();

const previousScore = existing?.score ?? null;
const isNewRecord = previousScore === null || score > previousScore;

// 최고 점수만 저장 (upsert)
if (isNewRecord) {
