import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-admin-secret',
};

// ── 보상 테이블 ──────────────────────────────────────────────────────────

/** 클래식 리더보드 난이도별 보상 (순위 → SKOR) */
const CLASSIC_REWARDS: Record<string, number[]> = {
  //  [1위, 2위, 3위, 4~10위(7명), 11~50위(40명)]
  normal:   [200, 120,  80,  40,  10],
  hard:     [300, 180, 120,  60,  15],
  extreme:  [500, 300, 200, 100,  25],
  physical: [800, 500, 350, 200,  50],
};

/** 배틀 리더보드 보상 (순위 구간 → SKOR) */
const BATTLE_REWARDS = [
  { maxRank:   1, skor: 1000 },
  { maxRank:   2, skor:  600 },
  { maxRank:   3, skor:  400 },
  { maxRank:  10, skor:  200 },
  { maxRank:  50, skor:   80 },
  { maxRank: 100, skor:   30 },
];

// ── 헬퍼: 순위 → 보상 계산 ──────────────────────────────────────────────

function classicRewardForRank(difficulty: string, rank: number): number {
  const table = CLASSIC_REWARDS[difficulty];
  if (!table) return 0;
  if (rank === 1) return table[0];
  if (rank === 2) return table[1];
  if (rank === 3) return table[2];
  if (rank <= 10) return table[3];
  if (rank <= 50) return table[4];
  return 0;
}

function battleRewardForRank(rank: number): number {
  for (const tier of BATTLE_REWARDS) {
    if (rank <= tier.maxRank) return tier.skor;
  }
  return 0;
}

// ── 헬퍼: SKOR 일괄 지급 ────────────────────────────────────────────────

async function bulkAddSkor(
  admin: ReturnType<typeof createClient>,
  rewardMap: Record<string, number>,
): Promise<void> {
  const userIds = Object.keys(rewardMap);
  if (userIds.length === 0) return;

  const { data: existing } = await admin
    .from('user_skor')
    .select('user_id, balance')
    .in('user_id', userIds);

  const balanceMap = Object.fromEntries(
    (existing ?? []).map((r: { user_id: string; balance: number }) => [r.user_id, r.balance])
  );

  await admin.from('user_skor').upsert(
    userIds.map(uid => ({
      user_id: uid,
      balance: Math.floor((balanceMap[uid] ?? 0) + rewardMap[uid]),
      updated_at: new Date().toISOString(),
    })),
    { onConflict: 'user_id' },
  );
}

// ── 헬퍼: 다음 시즌 row 계산 ────────────────────────────────────────────

function nextSeasonRow(current: { id: number; starts_at: string }) {
  const d = new Date(current.starts_at);
  d.setMonth(d.getMonth() + 1);
  d.setDate(1);
  const y = d.getFullYear();
  const m = d.getMonth() + 1;
  return {
    id: current.id + 1,
    name: `${y}년 ${m}월 시즌`,
    starts_at: d.toISOString(),
    ends_at: null,
  };
}

// ── 메인 핸들러 ─────────────────────────────────────────────────────────

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  // 관리자 시크릿 검증
  const adminSecret = req.headers.get('x-admin-secret');
  if (!adminSecret || adminSecret !== Deno.env.get('SEASON_END_SECRET')) {
    return new Response(
      JSON.stringify({ error: 'Unauthorized' }),
      { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  }

  try {
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    );

    // 1. 현재 진행 중인 시즌 조회
    const { data: currentSeason, error: seasonError } = await supabaseAdmin
      .from('seasons')
      .select('id, name, starts_at')
      .is('ends_at', null)
      .order('id', { ascending: false })
      .limit(1)
      .single();

    if (seasonError || !currentSeason) {
      return new Response(
        JSON.stringify({ error: 'No active season found' }),
        { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const seasonId: number = currentSeason.id;

    // 2. 클래식 + 배틀 상위 목록 병렬 조회
    const difficulties = ['normal', 'hard', 'extreme', 'physical'];
    const [normalTop, hardTop, extremeTop, physicalTop, battleTop] = await Promise.all([
      supabaseAdmin.from('leaderboard').select('user_id, score')
        .eq('difficulty', 'normal').eq('season_id', seasonId)
        .order('score', { ascending: false }).limit(50),
      supabaseAdmin.from('leaderboard').select('user_id, score')
        .eq('difficulty', 'hard').eq('season_id', seasonId)
        .order('score', { ascending: false }).limit(50),
      supabaseAdmin.from('leaderboard').select('user_id, score')
        .eq('difficulty', 'extreme').eq('season_id', seasonId)
        .order('score', { ascending: false }).limit(50),
      supabaseAdmin.from('leaderboard').select('user_id, score')
        .eq('difficulty', 'physical').eq('season_id', seasonId)
        .order('score', { ascending: false }).limit(50),
      supabaseAdmin.from('battle_records').select('user_id, rating_points')
        .eq('season_id', seasonId)
        .order('rating_points', { ascending: false }).limit(100),
    ]);

    // 3. 보상 집계 (동일 유저 중복 지급 가능 — 각 리더보드 독립)
    const rewardMap: Record<string, number> = {};
    const addReward = (userId: string, amount: number) => {
      rewardMap[userId] = (rewardMap[userId] ?? 0) + amount;
    };

    const classicResults = [normalTop, hardTop, extremeTop, physicalTop];
    classicResults.forEach((result, i) => {
      const diff = difficulties[i];
      (result.data ?? []).forEach((row: { user_id: string }, idx: number) => {
        const reward = classicRewardForRank(diff, idx + 1);
        if (reward > 0) addReward(row.user_id, reward);
      });
    });

    (battleTop.data ?? []).forEach((row: { user_id: string }, idx: number) => {
      const reward = battleRewardForRank(idx + 1);
      if (reward > 0) addReward(row.user_id, reward);
    });

    // 4. SKOR 일괄 지급
    await bulkAddSkor(supabaseAdmin, rewardMap);

    // 5. 현재 시즌 종료 처리
    await supabaseAdmin
      .from('seasons')
      .update({ ends_at: new Date().toISOString() })
      .eq('id', seasonId);

    // 6. 다음 시즌 자동 생성
    const nextSeason = nextSeasonRow(currentSeason);
    await supabaseAdmin.from('seasons').upsert(nextSeason, { onConflict: 'id' });

    return new Response(
      JSON.stringify({
        success: true,
        endedSeasonId: seasonId,
        nextSeasonId: nextSeason.id,
        nextSeasonName: nextSeason.name,
        rewardedUsers: Object.keys(rewardMap).length,
        totalSkorDistributed: Object.values(rewardMap).reduce((a, b) => a + b, 0),
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  } catch (error) {
    console.error('Unexpected error:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  }
});

