import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-admin-secret',
};

// ── 보상 테이블 ──────────────────────────────────────────────────────────

/** 클래식 리더보드 난이도별 보상 (순위 → SKOR) */
const CLASSIC_REWARDS: Record<string, number[]> = {
  //  [1위, 2위, 3위, 4~10위, 11~50위]
  normal:   [200, 120,  80,  40,  10],
  hard:     [300, 180, 120,  60,  15],
  extreme:  [500, 300, 200, 100,  25],
  physical: [800, 500, 350, 200,  50],
};

/** 배틀 리더보드 보상 (순위 구간 → SKOR) */
const BATTLE_REWARDS = [
  { maxRank:   1, skor: 1000 },
  { maxRank:   2, skor:  600 },
  { maxRank:   3, skor:  400 },
  { maxRank:  10, skor:  200 },
  { maxRank:  50, skor:   80 },
  { maxRank: 100, skor:   30 },
];

// ── 헬퍼: 순위 → 보상 계산 ──────────────────────────────────────────────

function classicRewardForRank(difficulty: string, rank: number): number {
  const table = CLASSIC_REWARDS[difficulty];
  if (!table) return 0;
  if (rank === 1) return table[0];
  if (rank === 2) return table[1];
  if (rank === 3) return table[2];
  if (rank <= 10) return table[3];
  if (rank <= 50) return table[4];
  return 0;
}

function battleRewardForRank(rank: number): number {
  for (const tier of BATTLE_REWARDS) {
    if (rank <= tier.maxRank) return tier.skor;
  }
  return 0;
}

// ── 헬퍼: 다음 시즌 row 계산 ────────────────────────────────────────────

function nextSeasonRow(current: { id: number; starts_at: string }) {
  const d = new Date(current.starts_at);
  d.setMonth(d.getMonth() + 1);
  d.setDate(1);
  const y = d.getFullYear();
  const m = d.getMonth() + 1;
  return {
    id: current.id + 1,
    name: `${y}년 ${m}월 시즌`,
    starts_at: d.toISOString(),
    ends_at: null,
  };
}

// ── 메인 핸들러 ─────────────────────────────────────────────────────────

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  // 관리자 시크릿 검증
  const adminSecret = req.headers.get('x-admin-secret');
  if (!adminSecret || adminSecret !== Deno.env.get('SEASON_END_SECRET')) {
    return new Response(
      JSON.stringify({ error: 'Unauthorized' }),
      { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  }

  try {
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    );

    // 1. 현재 진행 중인 시즌 조회
