    }[] = [];

    const classicResults = [normalTop, hardTop, extremeTop, physicalTop];
    classicResults.forEach((result, i) => {
      const diff = difficulties[i];
      (result.data ?? []).forEach((row: { user_id: string }, idx: number) => {
        const rank = idx + 1;
        const skor = classicRewardForRank(diff, rank);
        if (skor > 0) {
          rewardRows.push({
            user_id: row.user_id,
            season_id: seasonId,
            reward_type: `classic_${diff}`,
            skor_amount: skor,
            rank,
          });
        }
      });
    });

    (battleTop.data ?? []).forEach((row: { user_id: string }, idx: number) => {
      const rank = idx + 1;
      const skor = battleRewardForRank(rank);
      if (skor > 0) {
        rewardRows.push({
          user_id: row.user_id,
          season_id: seasonId,
          reward_type: 'battle',
          skor_amount: skor,
