    if (rewardRows.length > 0) {
      // ON CONFLICT DO NOTHING: 이미 생성된 보상은 덮어쓰지 않음 (claimed 보상 보호)
      await supabaseAdmin
        .from('season_rewards')
        .upsert(rewardRows, { onConflict: 'user_id,season_id,reward_type', ignoreDuplicates: true });
    }

    // 4. 현재 시즌 종료 처리
    await supabaseAdmin
      .from('seasons')
      .update({ ends_at: new Date().toISOString() })
      .eq('id', seasonId);

    // 5. 다음 시즌 자동 생성
    const nextSeason = nextSeasonRow(currentSeason);
    await supabaseAdmin.from('seasons').upsert(nextSeason, { onConflict: 'id' });

    const totalSkor = rewardRows.reduce((sum, r) => sum + r.skor_amount, 0);

    return new Response(
      JSON.stringify({
        success: true,
        endedSeasonId: seasonId,
        nextSeasonId: nextSeason.id,
        nextSeasonName: nextSeason.name,
