    // 2. 클래식 + 배틀 상위 목록 병렬 조회
    const difficulties = ['normal', 'hard', 'extreme', 'physical'];
    const [normalTop, hardTop, extremeTop, physicalTop, battleTop] = await Promise.all([
      supabaseAdmin.from('leaderboard').select('user_id, score')
