import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    // JWT 인증 필수
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: 'Missing authorization header' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const supabaseUser = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
      { global: { headers: { Authorization: authHeader } } },
    );

    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    if (authError || !user) {
      return new Response(
        JSON.stringify({ error: 'Unauthorized' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    // category: 'classic' (모든 클래식 난이도) | 'battle'
    const { category } = await req.json();
    if (category !== 'classic' && category !== 'battle') {
      return new Response(
        JSON.stringify({ error: "Invalid category: must be 'classic' or 'battle'" }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    );

    // 미수령 보상 조회 (종료된 시즌 한정)
    // reward_type prefix로 카테고리 필터 ('classic_*' or 'battle')
    const filterOp = category === 'classic'
      ? supabaseAdmin
          .from('season_rewards')
          .select('user_id, season_id, reward_type, skor_amount, rank')
          .eq('user_id', user.id)
          .is('claimed_at', null)
          .like('reward_type', 'classic_%')
      : supabaseAdmin
          .from('season_rewards')
          .select('user_id, season_id, reward_type, skor_amount, rank')
          .eq('user_id', user.id)
          .is('claimed_at', null)
          .eq('reward_type', 'battle');

    const { data: pending, error: fetchError } = await filterOp;

    if (fetchError) {
      console.error('Fetch error:', fetchError);
      return new Response(
        JSON.stringify({ error: 'Failed to fetch pending rewards' }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    if (!pending || pending.length === 0) {
      return new Response(
        JSON.stringify({ success: true, claimedAmount: 0, details: [] }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
      );
    }

    // 보상 합산
    const totalSkor = pending.reduce(
      (sum: number, r: { skor_amount: number }) => sum + r.skor_amount, 0
    );

    // SKOR 잔액 조회 후 추가
    const { data: skorRow } = await supabaseAdmin
      .from('user_skor')
      .select('balance')
      .eq('user_id', user.id)
      .single();
    const currentBalance: number = (skorRow as { balance: number } | null)?.balance ?? 0;
    const newBalance = currentBalance + totalSkor;

    await supabaseAdmin.from('user_skor').upsert(
      { user_id: user.id, balance: newBalance, updated_at: new Date().toISOString() },
      { onConflict: 'user_id' },
    );

    // 보상 레코드 claimed_at 업데이트
    const claimedAt = new Date().toISOString();
    for (const r of pending as { season_id: number; reward_type: string }[]) {
      await supabaseAdmin
        .from('season_rewards')
        .update({ claimed_at: claimedAt })
        .eq('user_id', user.id)
        .eq('season_id', r.season_id)
        .eq('reward_type', r.reward_type);
    }

    return new Response(
      JSON.stringify({
        success: true,
        claimedAmount: totalSkor,
        newBalance,
        details: pending.map((r: { season_id: number; reward_type: string; skor_amount: number; rank: number }) => ({
          seasonId: r.season_id,
          rewardType: r.reward_type,
          skor: r.skor_amount,
          rank: r.rank,
        })),
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  } catch (error) {
    console.error('Unexpected error:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    );
  }
});

