private async handleBattleClaim(
  bg: Phaser.GameObjects.Rectangle,
  txt: Phaser.GameObjects.Text,
) {
  if (!bg.active || !txt.active) return;
  bg.disableInteractive();
  txt.setText('수령 중...');

  try {
    const result = await claimSeasonReward('battle');
    if (result.claimedAmount > 0) {
      txt.setText(`✅ +${result.claimedAmount} SKOR 수령 완료!`).setColor('#ffffff');
      bg.setFillStyle(0x555555).setStrokeStyle(2, 0x888888);
      this.time.delayedCall(2000, () => {
        if (bg.active) bg.setVisible(false);
        if (txt.active) txt.setVisible(false);
      });
    } else {
      bg.setVisible(false);
      txt.setVisible(false);
    }
  } catch {
    txt.setText('수령 실패 — 다시 시도').setColor('#ff6666');
    bg.setInteractive({ useHandCursor: true });
  }
}

