     1→import { supabase } from './supabase';
     2→
     3→export interface SeasonReward {
     4→  seasonId: number;
     5→  rewardType: string;   // 'classic_normal' | 'classic_hard' | 'classic_extreme' | 'classic_physical' | 'battle'
     6→  skorAmount: number;
     7→  rank: number;
     8→}
     9→
    10→export interface ClaimResult {
    11→  success: boolean;
    12→  claimedAmount: number;
    13→  newBalance: number;
    14→  details: Array<{ seasonId: number; rewardType: string; skor: number; rank: number }>;
    15→}
    16→
    17→/** 미수령 시즌 보상 조회 (RLS: 자신의 것만) */
    18→export async function getPendingRewards(): Promise<SeasonReward[]> {
    19→  const { data, error } = await supabase
    20→    .from('season_rewards')
    21→    .select('season_id, reward_type, skor_amount, rank')
    22→    .is('claimed_at', null);
    23→
    24→  if (error || !data) return [];
    25→
    26→  return data.map((r: { season_id: number; reward_type: string; skor_amount: number; rank: number }) => ({
    27→    seasonId: r.season_id,
    28→    rewardType: r.reward_type,
    29→    skorAmount: r.skor_amount,
    30→    rank: r.rank,
    31→  }));
    32→}
    33→
    34→/** 카테고리별 미수령 보상 합산 금액 */
    35→export function sumPending(rewards: SeasonReward[], category: 'classic' | 'battle'): number {
    36→  return rewards
    37→    .filter(r => category === 'battle' ? r.rewardType === 'battle' : r.rewardType.startsWith('classic_'))
    38→    .reduce((sum, r) => sum + r.skorAmount, 0);
    39→}
    40→
    41→/** 시즌 보상 수령 */
    42→export async function claimSeasonReward(category: 'classic' | 'battle'): Promise<ClaimResult> {
    43→  const { data, error } = await supabase.functions.invoke('claim-season-reward', {
    44→    body: { category },
    45→  });
    46→
    47→  if (error) {
    48→    throw new Error(error.message || 'Failed to claim season reward');
    49→  }
    50→
    51→  return data as ClaimResult;
    52→}
    53→

