    96→    // 이미 상위 N명 뷰에 있으면 추가 쿼리 없이 entries에서 바로 계산
    97→    let currentUserRank: {
    98→      rank: number;
    99→      totalWins: number;
   100→      winRate: number;
   101→      ratingPoints: number;
   102→      friendlyWins: number;
   103→      friendlyLosses: number;
   104→      friendlyDisconnects: number;
   105→    } | null = null;
   106→
   107→    if (currentUserId) {
   108→      // 랭크드 전적 + 친선전 전적 병렬 조회 (별도 테이블)
   109→      const [recordResp, friendlyResp] = await Promise.all([
   110→        supabaseAdmin
   111→          .from('battle_records')
   112→          .select('wins, losses, disconnects, rating_points')
   113→          .eq('user_id', currentUserId)
   114→          .eq('season_id', currentSeasonId)
   115→          .maybeSingle(),
   116→        supabaseAdmin
   117→          .from('battle_friendly_records')
   118→          .select('friendly_wins, friendly_losses, friendly_disconnects')
   119→          .eq('user_id', currentUserId)
   120→          .maybeSingle(),
   121→      ]);
   122→
   123→      const userRecord = recordResp.data;
   124→      const friendlyRecord = friendlyResp.data;
   125→
   126→      if (userRecord) {
   127→        const rp: number = (userRecord as { rating_points: number }).rating_points ?? 0;
   128→        const totalWins = (userRecord.wins as number) + (userRecord.disconnects as number);
   129→        const myInTop = entries.find(e => e.userId === currentUserId);
   130→        let rank: number;
   131→
   132→        if (myInTop) {
   133→          rank = myInTop.rank;
   134→        } else {
   135→          const { data: rankResult } = await supabaseAdmin
   136→            .rpc('get_battle_rank_by_rp', { p_rp: rp, p_season_id: currentSeasonId });
   137→          rank = Number(rankResult ?? 0) + 1;
   138→        }
   139→
   140→        const totalGames =
   141→          (userRecord.wins as number) +
   142→          (userRecord.losses as number) +
   143→          (userRecord.disconnects as number);
   144→        const winRate = totalGames === 0
   145→          ? 0
   146→          : Math.round(totalWins / totalGames * 1000) / 10;
   147→
   148→        currentUserRank = {
   149→          rank,
   150→          totalWins,
   151→          winRate,
   152→          ratingPoints: rp,
   153→          friendlyWins: (friendlyRecord?.friendly_wins as number) ?? 0,
   154→          friendlyLosses: (friendlyRecord?.friendly_losses as number) ?? 0,
   155→          friendlyDisconnects: (friendlyRecord?.friendly_disconnects as number) ?? 0,
   156→        };
   157→      }
   158→    }
   159→
   160→    return new Response(
   161→      JSON.stringify({
   162→        success: true,
   163→        seasonId: currentSeasonId,
   164→        seasonName,
   165→        seasonEndsAt,
   166→        leaderboard: entries,
   167→        currentUserRank,
   168→      }),
   169→      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   170→    );
   171→  } catch (error) {
   172→    console.error('Unexpected error:', error);
   173→    return new Response(
   174→      JSON.stringify({ error: 'Internal server error' }),
   175→      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   176→    );
   177→  }
   178→});
