     1→import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
     2→
     3→const corsHeaders = {
     4→  'Access-Control-Allow-Origin': '*',
     5→  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
     6→};
     7→
     8→Deno.serve(async (req: Request) => {
     9→  if (req.method === 'OPTIONS') {
    10→    return new Response('ok', { headers: corsHeaders });
    11→  }
    12→
    13→  try {
    14→    // JWT 인증 필수
    15→    const authHeader = req.headers.get('Authorization');
    16→    if (!authHeader) {
    17→      return new Response(
    18→        JSON.stringify({ error: 'Missing authorization header' }),
    19→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    20→      );
    21→    }
    22→
    23→    const supabaseUser = createClient(
    24→      Deno.env.get('SUPABASE_URL') ?? '',
    25→      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
    26→      { global: { headers: { Authorization: authHeader } } },
    27→    );
    28→
    29→    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    30→    if (authError || !user) {
    31→      return new Response(
    32→        JSON.stringify({ error: 'Unauthorized' }),
    33→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    34→      );
    35→    }
    36→
    37→    // category: 'classic' (모든 클래식 난이도) | 'battle'
    38→    const { category } = await req.json();
    39→    if (category !== 'classic' && category !== 'battle') {
    40→      return new Response(
    41→        JSON.stringify({ error: "Invalid category: must be 'classic' or 'battle'" }),
    42→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    43→      );
    44→    }
    45→
    46→    const supabaseAdmin = createClient(
    47→      Deno.env.get('SUPABASE_URL') ?? '',
    48→      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    49→    );
    50→
    51→    // 미수령 보상 조회 (종료된 시즌 한정)
    52→    // reward_type prefix로 카테고리 필터 ('classic_*' or 'battle')
    53→    const filterOp = category === 'classic'
    54→      ? supabaseAdmin
    55→          .from('season_rewards')
    56→          .select('user_id, season_id, reward_type, skor_amount, rank')
    57→          .eq('user_id', user.id)
    58→          .is('claimed_at', null)
    59→          .like('reward_type', 'classic_%')
    60→      : supabaseAdmin
    61→          .from('season_rewards')
    62→          .select('user_id, season_id, reward_type, skor_amount, rank')
    63→          .eq('user_id', user.id)
    64→          .is('claimed_at', null)
    65→          .eq('reward_type', 'battle');
    66→
    67→    const { data: pending, error: fetchError } = await filterOp;
    68→
    69→    if (fetchError) {
    70→      console.error('Fetch error:', fetchError);
    71→      return new Response(
    72→        JSON.stringify({ error: 'Failed to fetch pending rewards' }),
    73→        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    74→      );
    75→    }
    76→
    77→    if (!pending || pending.length === 0) {
    78→      return new Response(
    79→        JSON.stringify({ success: true, claimedAmount: 0, details: [] }),
    80→        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    81→      );
    82→    }
    83→
    84→    // 보상 합산
    85→    const totalSkor = pending.reduce(
    86→      (sum: number, r: { skor_amount: number }) => sum + r.skor_amount, 0
    87→    );
    88→
    89→    // SKOR 잔액 조회 후 추가
    90→    const { data: skorRow } = await supabaseAdmin
    91→      .from('user_skor')
    92→      .select('balance')
    93→      .eq('user_id', user.id)
    94→      .single();
    95→    const currentBalance: number = (skorRow as { balance: number } | null)?.balance ?? 0;
    96→    const newBalance = currentBalance + totalSkor;
    97→
    98→    await supabaseAdmin.from('user_skor').upsert(
    99→      { user_id: user.id, balance: newBalance, updated_at: new Date().toISOString() },
   100→      { onConflict: 'user_id' },
   101→    );
   102→
   103→    // 보상 레코드 claimed_at 업데이트
   104→    const claimedAt = new Date().toISOString();
   105→    for (const r of pending as { season_id: number; reward_type: string }[]) {
   106→      await supabaseAdmin
   107→        .from('season_rewards')
   108→        .update({ claimed_at: claimedAt })
   109→        .eq('user_id', user.id)
   110→        .eq('season_id', r.season_id)
   111→        .eq('reward_type', r.reward_type);
   112→    }
   113→
   114→    return new Response(
   115→      JSON.stringify({
   116→        success: true,
   117→        claimedAmount: totalSkor,
   118→        newBalance,
   119→        details: pending.map((r: { season_id: number; reward_type: string; skor_amount: number; rank: number }) => ({
   120→          seasonId: r.season_id,
   121→          rewardType: r.reward_type,
   122→          skor: r.skor_amount,
   123→          rank: r.rank,
   124→        })),
   125→      }),
   126→      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   127→    );
   128→  } catch (error) {
   129→    console.error('Unexpected error:', error);
   130→    return new Response(
   131→      JSON.stringify({ error: 'Internal server error' }),
   132→      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
   133→    );
   134→  }
   135→});
