    52→// ── 랭크 캐시 (localStorage + djb2 서명) ──────────────────────────────
    53→
    54→const _CACHE_KEY     = 'battleRatingCache';
    55→const _CACHE_SIG_KEY = 'battleRatingCacheSig';
    56→const _CACHE_SALT    = 'ddong-battle-rating-\u0076\u0031';
    57→
    58→interface RatingCache { rp: number; rank: number | null; seasonId: number; }
    59→
    60→function _signCache(c: RatingCache): string {
    61→  const str = `rp:${c.rp},rank:${c.rank ?? 'null'},sid:${c.seasonId}` + _CACHE_SALT;
    62→  let h = 5381;
    63→  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
    64→  return h.toString(36);
    65→}
    66→
    67→/**
    68→ * 캐시된 내 RP/랭크 반환. 서명 불일치 시 null 반환.
    69→ * @param currentSeasonId 제공 시 seasonId 불일치면 null 반환 (시즌 변경 감지)
    70→ */
    71→export function getCachedMyRating(currentSeasonId?: number): RatingCache | null {
    72→  try {
    73→    const raw = localStorage.getItem(_CACHE_KEY);
    74→    const sig = localStorage.getItem(_CACHE_SIG_KEY);
    75→    if (!raw || !sig) return null;
    76→    const cache = JSON.parse(raw) as RatingCache;
    77→    if (sig !== _signCache(cache)) return null;
    78→    if (currentSeasonId !== undefined && cache.seasonId !== currentSeasonId) return null;
    79→    return cache;
    80→  } catch {
    81→    return null;
    82→  }
    83→}
