    25→      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
    26→      { global: { headers: { Authorization: authHeader } } },
    27→    );
    28→
    29→    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    30→    if (authError || !user) {
    31→      return new Response(
    32→        JSON.stringify({ error: 'Unauthorized' }),
    33→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    34→      );
    35→    }
    36→
    37→    // category: 'classic' (모든 클래식 난이도) | 'battle'
    38→    const { category } = await req.json();
    39→    if (category !== 'classic' && category !== 'battle') {
    40→      return new Response(
    41→        JSON.stringify({ error: "Invalid category: must be 'classic' or 'battle'" }),
    42→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    43→      );
    44→    }
    45→
    46→    const supabaseAdmin = createClient(
