    52→// ── 랭크 캐시 (localStorage + djb2 서명) ──────────────────────────────
    53→
    54→const _CACHE_KEY     = 'battleRatingCache';
    55→const _CACHE_SIG_KEY = 'battleRatingCacheSig';
    56→const _CACHE_SALT    = 'ddong-battle-rating-\u0076\u0031';
    57→
    58→interface RatingCache { rp: number; rank: number | null; seasonId: number; }
    59→
    60→function _signCache(c: RatingCache): string {
    61→  const str = `rp:${c.rp},rank:${c.rank ?? 'null'},sid:${c.seasonId}` + _CACHE_SALT;
    62→  let h = 5381;
    63→  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
    64→  return h.toString(36);
    65→}
    66→
    67→/**
    68→ * 캐시된 내 RP/랭크 반환. 서명 불일치 시 null 반환.
    69→ * @param currentSeasonId 제공 시 seasonId 불일치면 null 반환 (시즌 변경 감지)
    70→ */
    71→export function getCachedMyRating(currentSeasonId?: number): RatingCache | null {
    72→  try {
    73→    const raw = localStorage.getItem(_CACHE_KEY);
    74→    const sig = localStorage.getItem(_CACHE_SIG_KEY);
    75→    if (!raw || !sig) return null;
    76→    const cache = JSON.parse(raw) as RatingCache;
    77→    if (sig !== _signCache(cache)) return null;
    78→    if (currentSeasonId !== undefined && cache.seasonId !== currentSeasonId) return null;
    79→    return cache;
    80→  } catch {
    81→    return null;
    82→  }
    83→}
    84→
    85→/** 내 RP/랭크를 캐시에 저장 (서명 포함). */
    86→export function setCachedMyRating(rp: number, rank: number | null, seasonId: number = 0): void {
    87→  const cache: RatingCache = { rp, rank, seasonId };
    88→  localStorage.setItem(_CACHE_KEY, JSON.stringify(cache));
    89→  localStorage.setItem(_CACHE_SIG_KEY, _signCache(cache));
    90→}
    91→
    92→/** 캐시 삭제 (전적 없음 확정 시). */
    93→export function clearCachedMyRating(): void {
    94→  localStorage.removeItem(_CACHE_KEY);
    95→  localStorage.removeItem(_CACHE_SIG_KEY);
    96→}
    97→
    98→/** 세션 취득 공통 헬퍼 — 없으면 익명 로그인 후 반환 */
    99→async function getOrCreateSession() {
   100→  let { data: { session } } = await supabase.auth.getSession();
   101→  if (!session) {
   102→    const { data: authData } = await supabase.auth.signInAnonymously();
   103→    session = authData.session;
   104→  }
   105→  return session;
   106→}
   107→
   108→/**
   109→ * 대전 결과를 서버에 제출
   110→ * opponentId: 상대 유저 UUID (RP 차이 기반 변동 계산에 사용)
   111→ */
   112→export async function submitBattleResult(
   113→  result: BattleResult,
   114→  opponentId?: string,
   115→  isRanked: boolean = true,
   116→): Promise<SubmitBattleResultResponse> {
   117→  const session = await getOrCreateSession();
   118→
   119→  const { data, error } = await supabase.functions.invoke('battle-result-submit', {
   120→    body: { result, opponentId, isRanked },
   121→    headers: session?.access_token
   122→      ? { Authorization: `Bearer ${session.access_token}` }
   123→      : undefined,
   124→  });
   125→
   126→  if (error) {
   127→    throw new Error(error.message || 'Failed to submit battle result');
   128→  }
   129→
   130→  return data as SubmitBattleResultResponse;
   131→}
   132→
   133→/**
   134→ * 내 RP/전적만 가볍게 조회 (리더보드 1명만 요청하여 페이로드 최소화)
   135→ * seasonId도 함께 반환하여 캐시 시즌 검증에 사용
   136→ */
   137→export async function getMyRating(): Promise<{
   138→  stats: BattleLeaderboardResponse['currentUserRank'];
   139→  seasonId: number;
