    this.checkPendingRewards();
  }

  private createDifficultyButtons() {
    this.difficultyButtons.forEach(btn => btn.destroy());
    this.difficultyButtons.clear();

    const difficulties: Difficulty[] = [
      DifficultyEnum.NORMAL,
      DifficultyEnum.HARD,
      DifficultyEnum.EXTREME,
      DifficultyEnum.PHYSICAL
    ];

    const buttonWidth = 70;
    const spacing = 85;
    const startX = 200 - (spacing * 1.5);
    const y = 105;

    difficulties.forEach((difficulty, index) => {
      const x = startX + (index * spacing);
      const isSelected = difficulty === this.selectedDifficulty;

      const button = this.add.rectangle(
        x,
        y,
        buttonWidth,
        35,
        isSelected ? 0xffff99 : 0xffffff,
        1
      );
      button.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);

      this.add.text(x, y, difficulty, {
        fontSize: '12px',
        color: '#000',
        fontStyle: 'bold'
      }).setOrigin(0.5);

      this.difficultyButtons.set(difficulty, button);
      button.setInteractive({ useHandCursor: true });

      button.on('pointerover', () => {
        if (difficulty !== this.selectedDifficulty) {
          button.setFillStyle(0xffffcc);
        }
      });

      button.on('pointerout', () => {
        if (difficulty !== this.selectedDifficulty) {
          button.setFillStyle(0xffffff);
        }
      });

      button.on('pointerdown', () => {
        this.selectDifficulty(difficulty);
      });
    });
  }

  private selectDifficulty(difficulty: Difficulty) {
    // 같은 난이도면 무시
    if (this.selectedDifficulty === difficulty) {
      return;
    }

    this.selectedDifficulty = difficulty;

    // 모든 버튼 스타일 재설정
    this.difficultyButtons.forEach((btn, diff) => {
      const isSelected = diff === difficulty;
      btn.setFillStyle(isSelected ? 0xffff99 : 0xffffff);
      btn.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
    });

    // 새로운 난이도 데이터 로드
    this.loadLeaderboard();
  }

  private async loadLeaderboard() {
    // 요청 ID 증가 (새로운 요청 시작)
    this.currentRequestId++;
    const requestId = this.currentRequestId;

    // 기존 랭킹 텍스트 제거
    this.leaderboardTexts.forEach(text => text.destroy());
    this.leaderboardTexts = [];

    if (this.errorText) {
      this.errorText.destroy();
      this.errorText = undefined;
    }

    // 로딩 표시
    if (!this.loadingText) {
      this.loadingText = this.add.text(200, 300, '로딩 중...', {
        fontSize: '20px',
        color: '#fff',
        stroke: '#000',
        strokeThickness: 3
      }).setOrigin(0.5);
    } else {
      this.loadingText.setVisible(true);
    }

    try {
      const response = await getLeaderboard(this.selectedDifficulty, 10);

      // 응답이 도착했을 때 최신 요청인지 확인
      if (requestId !== this.currentRequestId) {
        // 이미 새로운 요청이 시작됨 - 이 응답은 무시
        return;
      }

      this.leaderboardData = response.leaderboard;

      if (this.loadingText) {
        this.loadingText.setVisible(false);
      }

      this.showSeasonBadge(this.seasonBadge!, response.seasonName, response.seasonEndsAt ?? null);
      this.displayLeaderboard();
    } catch (error) {
      // 에러가 발생했을 때도 최신 요청인지 확인
      if (requestId !== this.currentRequestId) {
        // 이미 새로운 요청이 시작됨 - 이 에러는 무시
        return;
      }

      console.error('Failed to load leaderboard:', error);

      if (this.loadingText) {
        this.loadingText.setVisible(false);
      }

      this.errorText = this.add.text(200, 300, '랭킹을 불러올 수 없습니다\n\n나중에 다시 시도해주세요', {
        fontSize: '16px',
        color: '#ff6666',
        stroke: '#000',
        strokeThickness: 3,
        align: 'center'
      }).setOrigin(0.5);
    }
  }

  private showSeasonBadge(name: string, endsAt: string | null) {
    if (!this.seasonBadge) return;
    let label = name;
    if (endsAt) {
      const days = Math.ceil((new Date(endsAt).getTime() - Date.now()) / 86400000);
      if (days > 0) label += ` | 종료까지 ${days}일`;
    }
    this.seasonBadge.setText(label);
  }

  private displayLeaderboard() {
    const startY = 150;
    const lineHeight = 35;

    // 헤더
    const headerText = this.add.text(200, startY, '순위    이름      점수', {
      fontSize: '16px',
      color: '#ffff00',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 4
    }).setOrigin(0.5);
    this.leaderboardTexts.push(headerText);

    // 랭킹 데이터 표시
    if (this.leaderboardData.length === 0) {
      const noDataText = this.add.text(200, startY + 50, '아직 랭킹이 없습니다\n\n첫 번째 플레이어가 되어보세요!', {
        fontSize: '18px',
        color: '#ccc',
        stroke: '#000',
        strokeThickness: 3,
        align: 'center'
      }).setOrigin(0.5);
      this.leaderboardTexts.push(noDataText);
      return;
    }

    this.leaderboardData.forEach((entry, index) => {
      const y = startY + 30 + (index * lineHeight);

      // 순위별 색상
      let color = '#ffffff';
      if (entry.rank === 1) color = '#FFD700'; // 금색
      else if (entry.rank === 2) color = '#C0C0C0'; // 은색
      else if (entry.rank === 3) color = '#CD7F32'; // 동색


      const rankText = `${entry.rank}`.padEnd(8, ' ');
      const nameText = entry.userName.padEnd(8, ' ');
      const scoreText = entry.score.toString().padStart(6, ' ');

      const text = this.add.text(
        200,
        y,
        `${rankText}${nameText}${scoreText}`,
        {
          fontSize: '16px',
          color: color,
          fontFamily: 'monospace',
          stroke: '#000',
          strokeThickness: 3
        }
      ).setOrigin(0.5);

      this.leaderboardTexts.push(text);
    });
  }

  private createClaimButton() {
    // 초기에는 숨김 — checkPendingRewards에서 보상 있으면 표시
    this.claimBtnBg = this.add.rectangle(200, 520, 300, 40, 0x1a5c1a)
      .setStrokeStyle(2, 0x44ee44)
      .setVisible(false);
    this.claimBtnTxt = this.add.text(200, 520, '', {
      fontSize: '15px', color: '#88ff88', fontStyle: 'bold',
      stroke: '#000', strokeThickness: 3,
    }).setOrigin(0.5).setVisible(false);
  }

  private async checkPendingRewards() {
    try {
      const rewards = await getPendingRewards();
      const total = sumPending(rewards, 'classic');
      if (total <= 0 || !this.claimBtnBg || !this.claimBtnTxt) return;

      this.claimBtnTxt.setText(`🎁 클래식 시즌 보상 수령 (+${total} SKOR)`);
      this.claimBtnBg.setVisible(true).setInteractive({ useHandCursor: true });
      this.claimBtnTxt.setVisible(true);

      this.claimBtnBg.on('pointerover', () => this.claimBtnBg?.setFillStyle(0x257a25));
      this.claimBtnBg.on('pointerout', () => this.claimBtnBg?.setFillStyle(0x1a5c1a));
      this.claimBtnBg.on('pointerdown', () => this.handleClaim());
    } catch {
      // 비크리티컬 — 보상 버튼 없으면 그냥 숨김 유지
    }
  }

  private async handleClaim() {
    if (!this.claimBtnBg || !this.claimBtnTxt) return;

    // 버튼 비활성화 (중복 클릭 방지)
    this.claimBtnBg.disableInteractive();
    this.claimBtnTxt.setText('수령 중...');

    try {
      const result = await claimSeasonReward('classic');
      if (result.claimedAmount > 0) {
        this.claimBtnTxt.setText(`✅ +${result.claimedAmount} SKOR 수령 완료!`).setColor('#ffffff');
        this.claimBtnBg.setFillStyle(0x555555).setStrokeStyle(2, 0x888888);
        // 2초 후 버튼 숨김
        this.time.delayedCall(2000, () => {
          this.claimBtnBg?.setVisible(false);
          this.claimBtnTxt?.setVisible(false);
        });
      } else {
        this.claimBtnBg.setVisible(false);
        this.claimBtnTxt.setVisible(false);
      }
    } catch {
      this.claimBtnTxt.setText('수령 실패 — 다시 시도해주세요').setColor('#ff6666');
      this.claimBtnBg.setInteractive({ useHandCursor: true });
    }
  }

  private createBackButton() {
    const button = this.add.rectangle(200, 560, 150, 40, 0xffffff, 1);
    button.setStrokeStyle(3, 0x000000);

    const text = this.add.text(200, 560, '← 뒤로가기', {
      fontSize: '18px',
      color: '#000',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    button.setInteractive({ useHandCursor: true });

    const elements = [button, text];
    elements.forEach(element => {
      element.on('pointerover', () => {
        button.setFillStyle(0xffff99);
      });

      element.on('pointerout', () => {
        button.setFillStyle(0xffffff);
      });

      element.on('pointerdown', () => {
        this.scene.start('ModeSelectScene');
      });
    });
  }
}

import type Phaser from 'phaser';
import { supabase } from '../utils/supabase';
import { getBattleLeaderboard, type BattleRecordEntry } from '../utils/battleLeaderboard';
import { getBattleTier, preloadTierImages } from '../utils/battleTier';
import BaseScene from './BaseScene';

export default class BattleLeaderboardScene extends BaseScene {
  private leaderboardEntries: BattleRecordEntry[] = [];
  private leaderboardTexts: Phaser.GameObjects.GameObject[] = [];
  private loadingText?: Phaser.GameObjects.Text;
  private seasonBadge?: Phaser.GameObjects.Text;
  private currentUserRank: {
    rank: number;
    totalWins: number;
    winRate: number;
    ratingPoints: number;
    friendlyWins: number;
    friendlyLosses: number;
    friendlyDisconnects: number;
  } | null = null;
  private currentUserId: string | null = null;

  constructor() {
    super('BattleLeaderboardScene');
  }

  preload() {
    if (!this.textures.exists('background2')) {
      this.load.image('background2', 'assets/backgrounds/background2.webp');
    }
    preloadTierImages(this);
  }

  create() {
    super.create();

    // 배경
    const bg = this.add.image(200, 300, 'background2');
    bg.setDisplaySize(400, 600);
    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.75);

    // 타이틀
    this.add.text(200, 40, '⚔️ 배틀 전적', {
      fontSize: '28px',
      color: '#ff4444',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 5,
    }).setOrigin(0.5);

    // 시즌 배지 (데이터 로드 후 채워짐)
    this.seasonBadge = this.add.text(200, 68, '', {
      fontSize: '13px',
      color: '#88ccff',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5);

    // 내 전적 영역 (로드 후 채워짐)
    this.loadingText = this.add.text(200, 300, '로딩 중...', {
      fontSize: '20px',
      color: '#ffffff',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5);

    // 뒤로가기
    const backBtn = this.add.text(200, 565, '← 대전 모드', {
      fontSize: '18px',
      color: '#aaaaaa',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5).setInteractive({ useHandCursor: true });
    backBtn.on('pointerover', () => backBtn.setColor('#ffffff'));
    backBtn.on('pointerout', () => backBtn.setColor('#aaaaaa'));
    backBtn.on('pointerdown', () => this.scene.start('BattleMatchScene'));

    // currentUserId를 먼저 확인한 뒤 리더보드 로드 (race condition 방지)
    supabase.auth.getUser()
      .then(({ data }) => {
        if (data.user?.id) this.currentUserId = data.user.id;
        return this.loadLeaderboard();
      })
      .catch(() => this.loadLeaderboard());
  }

  private async loadLeaderboard() {
    try {
      const response = await getBattleLeaderboard(20);
      this.leaderboardEntries = response.leaderboard;
      this.currentUserRank = response.currentUserRank;

      if (this.loadingText) {
        this.loadingText.setVisible(false);
      }

      this.showSeasonBadge(response.seasonName, response.seasonEndsAt ?? null);
      this.displayLeaderboard();
    } catch (error) {
      console.error('Failed to load battle leaderboard:', error);

      if (this.loadingText) {
        this.loadingText.setVisible(false);
      }

      this.add.text(200, 300, '전적을 불러올 수 없습니다\n나중에 다시 시도해주세요', {
        fontSize: '16px',
        color: '#ff6666',
        stroke: '#000',
        strokeThickness: 3,
        align: 'center',
      }).setOrigin(0.5);
    }
  }

  private showSeasonBadge(name: string, endsAt: string | null) {
    if (!this.seasonBadge) return;
    let label = name;
    if (endsAt) {
      const days = Math.ceil((new Date(endsAt).getTime() - Date.now()) / 86400000);
      if (days > 0) label += ` | 종료까지 ${days}일`;
    }
    this.seasonBadge.setText(label);
  }

  private displayLeaderboard() {
    // 기존 객체 제거
    for (const obj of this.leaderboardTexts) {
      if (obj.active) obj.destroy();
    }
    this.leaderboardTexts = [];

    // 컬럼 X 위치 (캔버스 400px 기준)
    const COL_RANK   = 28;   // right-align
    const COL_NAME   = 44;   // left-align
    const COL_TIER_IMG  = 148;  // image center
    const COL_TIER_NAME = 162;  // left-align
    const COL_RP     = 258;  // right-align
    const COL_RATE   = 362;  // right-align

    const txtStyle = (color: string) => ({
      fontSize: '13px', color, fontFamily: 'monospace',
      stroke: '#000', strokeThickness: 3,
    });

    // 내 전적 요약
    if (this.currentUserRank) {
      const { winRate, rank, ratingPoints, friendlyWins, friendlyLosses, friendlyDisconnects } = this.currentUserRank;
      const myEntry = this.leaderboardEntries.find(e => e.userId === this.currentUserId);
      const wins = myEntry?.wins ?? 0;
      const losses = myEntry?.losses ?? 0;
      const disconnects = myEntry?.disconnects ?? 0;
      const myTier = getBattleTier(ratingPoints);

      // 티어 이미지 (좌측 소형)
      const myTierImg = this.add.image(13, 88, myTier.imgKey).setDisplaySize(20, 20);
      this.leaderboardTexts.push(myTierImg);

      // 랭크 전적
      const rankSummary = this.add.text(
        200, 88,
        `${myTier.name} | ${ratingPoints} RP | 랭크: ${wins}승 ${disconnects}부 ${losses}패 | ${winRate}% (${rank}위)`,
        { fontSize: '11px', color: '#FFD700', stroke: '#000', strokeThickness: 3 },
      ).setOrigin(0.5);
      this.leaderboardTexts.push(rankSummary);

      // 친선전 전적
      const fw = friendlyWins ?? 0;
      const fl = friendlyLosses ?? 0;
      const fd = friendlyDisconnects ?? 0;
      const friendlySummary = this.add.text(
        200, 107,
        `친선전: ${fw}승 ${fd}부 ${fl}패`,
        { fontSize: '11px', color: '#88ccff', stroke: '#000', strokeThickness: 3 },
      ).setOrigin(0.5);
      this.leaderboardTexts.push(friendlySummary);
    }

    // 구분선
    const divider = this.add.rectangle(200, 125, 360, 2, 0x555555);
    this.leaderboardTexts.push(divider);

    // 헤더
    const headerStyle = { fontSize: '13px', color: '#ffff00', fontStyle: 'bold', fontFamily: 'monospace', stroke: '#000', strokeThickness: 3 };
    this.leaderboardTexts.push(this.add.text(COL_RANK,      143, '순위', headerStyle).setOrigin(1, 0.5));
    this.leaderboardTexts.push(this.add.text(COL_NAME,      143, '이름', headerStyle).setOrigin(0, 0.5));
    this.leaderboardTexts.push(this.add.text(COL_TIER_IMG,  143, '티어', headerStyle).setOrigin(0.5, 0.5));
    this.leaderboardTexts.push(this.add.text(COL_RP,        143, 'RP',   headerStyle).setOrigin(1, 0.5));
    this.leaderboardTexts.push(this.add.text(COL_RATE,      143, '승률', headerStyle).setOrigin(1, 0.5));

    if (this.leaderboardEntries.length === 0) {
      const noData = this.add.text(200, 300, '아직 대전 기록이 없습니다\n첫 번째 플레이어가 되어보세요!', {
        fontSize: '16px', color: '#cccccc', stroke: '#000', strokeThickness: 3, align: 'center',
      }).setOrigin(0.5);
      this.leaderboardTexts.push(noData);
      return;
    }

    const startY = 170;
    const lineH = 31;

    this.leaderboardEntries.forEach((entry, index) => {
      const y = startY + index * lineH;
      const isMe = entry.userId === this.currentUserId;
      const tier = getBattleTier(entry.ratingPoints);

      // 현재 유저 행 하이라이트
      if (isMe) {
        this.leaderboardTexts.push(this.add.rectangle(200, y, 380, 28, 0x8B6914, 0.5));
      }

      // 순위 색상
      let color = '#ffffff';
      if (entry.rank === 1) color = '#FFD700';
      else if (entry.rank === 2) color = '#C0C0C0';
      else if (entry.rank === 3) color = '#CD7F32';
      else if (isMe) color = '#FFD700';

      this.leaderboardTexts.push(
        this.add.text(COL_RANK, y, `${entry.rank}`, txtStyle(color)).setOrigin(1, 0.5),
      );
      this.leaderboardTexts.push(
        this.add.text(COL_NAME, y, entry.userName, txtStyle(color)).setOrigin(0, 0.5),
      );
      // 티어 이미지
      this.leaderboardTexts.push(
        this.add.image(COL_TIER_IMG, y, tier.imgKey).setDisplaySize(20, 20),
      );
      this.leaderboardTexts.push(
        this.add.text(COL_TIER_NAME, y, tier.name, txtStyle(tier.color)).setOrigin(0, 0.5),
      );
      this.leaderboardTexts.push(
        this.add.text(COL_RP, y, `${entry.ratingPoints}`, txtStyle(color)).setOrigin(1, 0.5),
      );
      this.leaderboardTexts.push(
        this.add.text(COL_RATE, y, `${entry.winRate}%`, txtStyle(color)).setOrigin(1, 0.5),
      );
    });
  }
}

