import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// 난이도별 물리적 최대 점수 (2시간 연속 플레이 기준)
const SCORE_CAPS: Record<string, number> = {
  easy: 10000,
  normal: 15000,
  hard: 20000,
  extreme: 30000,
  physical: 30000,
};

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const { score, difficulty, userName, sessionId, verification, characterType } = await req.json();

    // 기본 입력 검증
    if (typeof score !== 'number' || score < 0) {
      return new Response(
        JSON.stringify({ error: 'Invalid score' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const validDifficulties = ['easy', 'normal', 'hard', 'extreme', 'physical'];
    if (!validDifficulties.includes(difficulty)) {
      return new Response(
        JSON.stringify({ error: 'Invalid difficulty' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    if (!userName || !/^[A-Z]{3}$/.test(userName)) {
      return new Response(
        JSON.stringify({ error: 'Invalid userName: must be 3 uppercase letters' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // 하드 캡: 물리적으로 불가능한 점수 차단
    if (score > (SCORE_CAPS[difficulty] ?? 10000)) {
      console.warn('Score exceeds hard cap', { score, difficulty });
      return new Response(
        JSON.stringify({ error: 'Score exceeds maximum possible value' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // JWT 인증
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: 'Missing authorization header' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const supabaseUser = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
      { global: { headers: { Authorization: authHeader } } }
    );

    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    if (authError || !user) {
      return new Response(
        JSON.stringify({ error: 'Unauthorized' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    // ── 세션 검증: 서버가 기록한 start_time 기준으로 경과 시간 확인 ──────────
    // UPDATE WHERE used=false RETURNING ... 패턴으로 원자적 검증 + 소비 처리
    // SELECT 후 UPDATE 방식은 동시 요청 시 race condition 가능 → 이 방식으로 방지
    if (sessionId) {
      const { data: session } = await supabaseAdmin
        .from('game_sessions')
        .update({ used: true })
        .eq('id', sessionId)
        .eq('used', false)
        .eq('user_id', user.id)
        .eq('difficulty', difficulty)
        .select('start_time')
        .single();

      // null → 세션 없음 / 이미 사용됨 / 소유자 불일치 / 난이도 불일치 중 하나
      if (!session) {
        return new Response(
          JSON.stringify({ error: 'Invalid or already used session' }),
          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      // 서버 시각 기준 경과 시간으로 점수 타당성 검증
      const nowMs = Date.now();
      const serverStartMs = new Date(session.start_time).getTime();
      const elapsedMs = nowMs - serverStartMs;
      const elapsedSec = elapsedMs / 1000;

      // 세션 만료 체크 (2시간 초과)
      if (elapsedMs > 2 * 60 * 60 * 1000) {
        return new Response(
          JSON.stringify({ error: 'Session expired' }),
          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      // 핵심 검증: 이 점수가 나오려면 최소 N초는 걸렸어야 함
      // 보너스 아이템(금똥/다이아/토파즈/무지개) + ability/synergy collectBonus는 시간 없이도 점수를 올리므로 제외
      // 1점 = 100ms → timeBasedScore점 = timeBasedScore * 0.1초, 50% 여유 적용
      const totalItemsCollected =
        (verification?.goldCollected ?? 0) +
        (verification?.diamondCollected ?? 0) +
        (verification?.topazCollected ?? 0) +
        (verification?.rainbowCollected ?? 0);
      // collectBonusTotal은 클라이언트 신고값이므로 수집 아이템당 최대 10점으로 상한 적용 (tampering 방지)
      const collectBonusTotal = Math.min(verification?.collectBonusTotal ?? 0, totalItemsCollected * 10);
      const bonusScore =
        (verification?.goldCollected ?? 0) * 20 +
        (verification?.diamondCollected ?? 0) * 40 +
        (verification?.topazCollected ?? 0) * 80 +
        (verification?.rainbowCollected ?? 0) * 90 +
        collectBonusTotal;
      const timeBasedScore = Math.max(0, score - bonusScore);
      const minRequiredSec = timeBasedScore * 0.1 * 0.5;

      // Edge Function cold start 보정: 클라이언트 신고 시각 기준 경과를 추가 허용
      // session.start_time이 실제 게임 시작보다 늦을 수 있음 (cold start)
      // 클라이언트 신고 시각을 최대 20초 범위 내에서 신뢰 (tampering 방지용 상한)
      const clientStartMs = verification?.gameStartTime ?? null;
      const COLD_START_TOLERANCE_MS = 20_000;
      let adjustedElapsedSec = elapsedSec;
      if (clientStartMs && clientStartMs < serverStartMs) {
        const effectiveStartMs = Math.max(clientStartMs, serverStartMs - COLD_START_TOLERANCE_MS);
        adjustedElapsedSec = (nowMs - effectiveStartMs) / 1000;
      }

      if (adjustedElapsedSec < minRequiredSec) {
        console.warn('Session time gate failed', { score, adjustedElapsedSec, minRequiredSec, elapsedSec });
        return new Response(
          JSON.stringify({ error: 'Score not achievable in elapsed time' }),
          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }
    } else if (verification) {
      // 세션 없이 구 방식 verification만 있는 경우 (하위 호환)
      const {
        gameStartTime,
        gameEndTime,
        goldCollected = 0,
        diamondCollected = 0,
        topazCollected = 0,
        rainbowCollected = 0,
      } = verification;

      const playDuration = gameEndTime - gameStartTime;
      const timeScore = Math.floor(playDuration / 100);
      const bonusScore =
        goldCollected * 20 +
        diamondCollected * 40 +
        topazCollected * 80 +
        rainbowCollected * 90;
      const expectedScore = timeScore + bonusScore;
      const tolerance = Math.max(expectedScore * 0.2, 10);

      if (score > expectedScore + tolerance) {
        console.warn('Score verification failed', { score, expectedScore, playDuration });
        return new Response(
          JSON.stringify({ error: 'Score verification failed' }),
          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }
    }

    // 현재 시즌 조회
    const { data: seasonId } = await supabaseAdmin.rpc('get_current_season_id');
    const currentSeasonId: number = seasonId ?? 0;

    // profiles 테이블에 이니셜 업데이트
    await supabaseAdmin
      .from('profiles')
      .update({ initials: userName })
      .eq('id', user.id);

    // 기존 점수 조회 (현재 시즌 한정)
    const { data: existing } = await supabaseAdmin
      .from('leaderboard')
      .select('score')
      .eq('user_id', user.id)
      .eq('difficulty', difficulty)
      .eq('season_id', currentSeasonId)
      .single();

    const previousScore = existing?.score ?? null;
    const isNewRecord = previousScore === null || score > previousScore;

    // 최고 점수만 저장 (upsert)
    if (isNewRecord) {
      const validCharacterTypes = [
        'chibi',
        'log', 'swap', 'sum', 'fork', 'seed', 'session', 'branch', 'hook', 'socket', 'index',
        'hacker', 'miner', 'maehwa', 'archieve', 'glitch', 'noise',
        'sentinel', 'legacy',
      ];
      const safeCharacterType = validCharacterTypes.includes(characterType) ? characterType : 'chibi';

      const { error: upsertError } = await supabaseAdmin
        .from('leaderboard')
        .upsert(
          {
            user_id: user.id,
            difficulty,
            score,
            season_id: currentSeasonId,
            character_type: safeCharacterType,
            updated_at: new Date().toISOString(),
          },
          { onConflict: 'user_id,difficulty,season_id' }
        );

      if (upsertError) {
        console.error('Upsert error:', upsertError);
        return new Response(
          JSON.stringify({ error: 'Failed to save score' }),
          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }
    }

    // 현재 순위 계산 (현재 시즌 한정)
    const { count: rank } = await supabaseAdmin
      .from('leaderboard')
      .select('*', { count: 'exact', head: true })
      .eq('difficulty', difficulty)
      .eq('season_id', currentSeasonId)
      .gt('score', isNewRecord ? score : (previousScore ?? 0));

    return new Response(
      JSON.stringify({
        success: true,
        isNewRecord,
        previousScore,
        newScore: isNewRecord ? score : (previousScore ?? score),
        rank: rank !== null ? rank + 1 : null,
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    console.error('Unexpected error:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

import { supabase } from './supabase';
import { type BattleResult } from '../types/BattleTypes';

export interface BattleRecordEntry {
  rank: number;
  userId: string;
  userName: string;
  wins: number;
  losses: number;
  disconnects: number;
  totalWins: number;
  winRate: number;
  ratingPoints: number;
  tierName: string;
  tierIcon: string;
}

export interface SubmitBattleResultResponse {
  success: boolean;
  previousRp: number;   // 클램핑 전 이전 RP (티어 변화 감지에 사용)
  ratingPoints: number;
  pointDelta: number;
  wins: number;
  losses: number;
  disconnects: number;
  friendlyWins: number;
  friendlyLosses: number;
  friendlyDisconnects: number;
  winRate: number;
  rank: number;
  tierName: string;
  tierIcon: string;
}

export interface BattleLeaderboardResponse {
  success: boolean;
  seasonId: number;
  seasonName: string;
  seasonEndsAt: string | null;
  leaderboard: BattleRecordEntry[];
  currentUserRank: {
    rank: number;
    totalWins: number;
    winRate: number;
    ratingPoints: number;
    friendlyWins: number;
    friendlyLosses: number;
    friendlyDisconnects: number;
  } | null;
}

// ── 랭크 캐시 (localStorage + djb2 서명) ──────────────────────────────

const _CACHE_KEY     = 'battleRatingCache';
const _CACHE_SIG_KEY = 'battleRatingCacheSig';
const _CACHE_SALT    = 'ddong-battle-rating-\u0076\u0031';

interface RatingCache { rp: number; rank: number | null; seasonId: number; }

function _signCache(c: RatingCache): string {
  const str = `rp:${c.rp},rank:${c.rank ?? 'null'},sid:${c.seasonId}` + _CACHE_SALT;
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
  return h.toString(36);
}

/**
 * 캐시된 내 RP/랭크 반환. 서명 불일치 시 null 반환.
 * @param currentSeasonId 제공 시 seasonId 불일치면 null 반환 (시즌 변경 감지)
 */
export function getCachedMyRating(currentSeasonId?: number): RatingCache | null {
  try {
    const raw = localStorage.getItem(_CACHE_KEY);
    const sig = localStorage.getItem(_CACHE_SIG_KEY);
    if (!raw || !sig) return null;
    const cache = JSON.parse(raw) as RatingCache;
    if (sig !== _signCache(cache)) return null;
    if (currentSeasonId !== undefined && cache.seasonId !== currentSeasonId) return null;
    return cache;
  } catch {
    return null;
  }
}

/** 내 RP/랭크를 캐시에 저장 (서명 포함). */
export function setCachedMyRating(rp: number, rank: number | null, seasonId: number = 0): void {
  const cache: RatingCache = { rp, rank, seasonId };
  localStorage.setItem(_CACHE_KEY, JSON.stringify(cache));
  localStorage.setItem(_CACHE_SIG_KEY, _signCache(cache));
}

/** 캐시 삭제 (전적 없음 확정 시). */
export function clearCachedMyRating(): void {
  localStorage.removeItem(_CACHE_KEY);
  localStorage.removeItem(_CACHE_SIG_KEY);
}

/** 세션 취득 공통 헬퍼 — 없으면 익명 로그인 후 반환 */
async function getOrCreateSession() {
  let { data: { session } } = await supabase.auth.getSession();
  if (!session) {
    const { data: authData } = await supabase.auth.signInAnonymously();
    session = authData.session;
  }
  return session;
}

/**
 * 대전 결과를 서버에 제출
 * opponentId: 상대 유저 UUID (RP 차이 기반 변동 계산에 사용)
 */
export async function submitBattleResult(
  result: BattleResult,
  opponentId?: string,
  isRanked: boolean = true,
): Promise<SubmitBattleResultResponse> {
  const session = await getOrCreateSession();

  const { data, error } = await supabase.functions.invoke('battle-result-submit', {
    body: { result, opponentId, isRanked },
    headers: session?.access_token
      ? { Authorization: `Bearer ${session.access_token}` }
      : undefined,
  });

  if (error) {
    throw new Error(error.message || 'Failed to submit battle result');
  }

  return data as SubmitBattleResultResponse;
}

/**
 * 내 RP/전적만 가볍게 조회 (리더보드 1명만 요청하여 페이로드 최소화)
 * seasonId도 함께 반환하여 캐시 시즌 검증에 사용
 */
export async function getMyRating(): Promise<{
  stats: BattleLeaderboardResponse['currentUserRank'];
  seasonId: number;
}> {
  const response = await getBattleLeaderboard(1);
  return { stats: response.currentUserRank, seasonId: response.seasonId ?? 0 };
}

/**
 * 배틀 리더보드 상위 N명 조회
 */
export async function getBattleLeaderboard(limit: number = 20): Promise<BattleLeaderboardResponse> {
  const session = await getOrCreateSession();

  const { data, error } = await supabase.functions.invoke('battle-leaderboard-top', {
    body: { limit },
    headers: session?.access_token
      ? { Authorization: `Bearer ${session.access_token}` }
      : undefined,
  });

  if (error) {
    throw new Error(error.message || 'Failed to fetch battle leaderboard');
  }

  return data as BattleLeaderboardResponse;
}

import { BattleResult, BattleEvent } from '../types/BattleTypes';
import { submitBattleResult, setCachedMyRating, type SubmitBattleResultResponse } from '../utils/battleLeaderboard';
import { getBattleTier, getTierIndex, preloadTierImages } from '../utils/battleTier';
import { BattleChannel } from '../utils/battleChannel';
import BaseScene from './BaseScene';

interface BattleResultData {
  result: BattleResult;
  roomCode: string;
  userId?: string;
  opponentId?: string;
  isRanked?: boolean;
}

/**
 * 대전 결과 씬
 * - 승리/패배/연결끊김 표시
 * - RP 변동 + 티어 표시
 * - 재도전: 양쪽 모두 요청 시 BattleMatchScene 자동 복귀
 * - 상대 재도전 의사 / 이탈 실시간 알림
 */
export default class BattleResultScene extends BaseScene {
  private result: BattleResult = BattleResult.WIN;
  private roomCode: string = '';
  private userId: string = '';
  private opponentId: string = '';
  private isRanked: boolean = false;
  private resultSubmitted: boolean = false;

  // RP UI
  private tierText?: Phaser.GameObjects.Text;
  private rpDeltaText?: Phaser.GameObjects.Text;
  private currentRpText?: Phaser.GameObjects.Text;
  private tierIconImg?: Phaser.GameObjects.Image;
  private tierUpgradeOldImg?: Phaser.GameObjects.Image;
  private tierArrowText?: Phaser.GameObjects.Text;

  // 재도전 채널
  private rematchChannel: BattleChannel | null = null;
  private myRematchRequested: boolean = false;
  private opponentRematchRequested: boolean = false;
  private rematchTransitioning: boolean = false;
  private opponentLeftHandled: boolean = false;

  // 재도전 UI
  private rematchBtn!: Phaser.GameObjects.Rectangle;
  private rematchBtnLabel!: Phaser.GameObjects.Text;
  private rematchStatusText!: Phaser.GameObjects.Text;

  constructor() {
    super('BattleResultScene');
  }

  init(data: BattleResultData) {
    this.result = data.result ?? BattleResult.WIN;
    this.roomCode = data.roomCode ?? '';
    this.userId = data.userId ?? '';
    this.opponentId = data.opponentId ?? '';
    this.isRanked = data.isRanked ?? false;
    this.resultSubmitted = false;
    this.myRematchRequested = false;
    this.opponentRematchRequested = false;
    this.rematchTransitioning = false;
    this.opponentLeftHandled = false;
  }

  preload() {
    if (!this.textures.exists('background2')) {
      this.load.image('background2', 'assets/backgrounds/background2.webp');
    }
    preloadTierImages(this);
  }

  create() {
    super.create();

    // 배경
    const bg = this.add.image(200, 300, 'background2');
    bg.setDisplaySize(400, 600);
    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.75);

    // 결과 텍스트
    const isWin = this.result === BattleResult.WIN || this.result === BattleResult.DISCONNECT;
    const resultText = this.result === BattleResult.WIN ? '🏆 승리! 🏆'
      : this.result === BattleResult.DISCONNECT ? '🏆 부전승 🏆'
      : '💀 패배... 💀';
    const titleColor = isWin ? '#FFD700' : '#ff4444';

    this.add.text(200, 85, resultText, {
      fontSize: '36px',
      color: titleColor,
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 6,
    }).setOrigin(0.5);

    // 티어/RP 영역
    if (this.isRanked) {
      // 랭크전: 전적 제출 후 채워짐 (y=120 영역에 티어 이미지가 들어올 자리 확보)
      this.tierText = this.add.text(200, 162, '전적 기록 중...', {
        fontSize: '15px',
        color: '#aaaaaa',
        stroke: '#000',
        strokeThickness: 3,
      }).setOrigin(0.5);

      this.rpDeltaText = this.add.text(200, 183, '', {
        fontSize: '18px',
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 4,
      }).setOrigin(0.5);

      this.currentRpText = this.add.text(200, 205, '', {
        fontSize: '13px',
        color: '#888888',
        stroke: '#000',
        strokeThickness: 3,
      }).setOrigin(0.5);
    } else {
      // 친선전: RP 변동 없음 표시
      this.add.text(200, 148, '친선전 — RP 변동 없음', {
        fontSize: '14px',
        color: '#666666',
        stroke: '#000',
        strokeThickness: 3,
      }).setOrigin(0.5);
    }

    if (this.isRanked) {
      // 랭크전: 재대전 없음 → 새 매칭 버튼
      const newMatchBtn = this.add.rectangle(200, 310, 250, 50, 0x7a5c00);
      newMatchBtn.setStrokeStyle(3, 0xFFD700);
      this.add.text(200, 310, '🎖️ 새 랭크 매칭', {
        fontSize: '20px',
        color: '#FFD700',
        fontStyle: 'bold',
      }).setOrigin(0.5);
      newMatchBtn.setInteractive({ useHandCursor: true });
      newMatchBtn.on('pointerover', () => newMatchBtn.setAlpha(0.8));
      newMatchBtn.on('pointerout', () => newMatchBtn.setAlpha(1));
      newMatchBtn.on('pointerdown', () => {
        if (this.rematchChannel) {
          this.rematchChannel.destroyImmediate();
          this.rematchChannel = null;
        }
        this.scene.start('BattleMatchScene');
      });
    } else {
      // 친선전: 기존 재대전 버튼 유지
      this.rematchStatusText = this.add.text(200, 250, '', {
        fontSize: '14px',
        color: '#FFD700',
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 3,
        align: 'center',
      }).setOrigin(0.5);

      this.rematchBtn = this.add.rectangle(200, 310, 250, 50, 0xe74c3c);
      this.rematchBtn.setStrokeStyle(3, 0xffffff);
      this.rematchBtnLabel = this.add.text(200, 310, '⚔️ 재대전', {
        fontSize: '20px',
        color: '#ffffff',
        fontStyle: 'bold',
      }).setOrigin(0.5);
      this.rematchBtn.setInteractive({ useHandCursor: true });
      this.rematchBtn.on('pointerover', () => {
        if (!this.myRematchRequested) this.rematchBtn.setAlpha(0.8);
      });
      this.rematchBtn.on('pointerout', () => this.rematchBtn.setAlpha(1));
      this.rematchBtn.on('pointerdown', () => this.handleRematchClick());
    }

    // 전적 보기 버튼
    const rankBtn = this.add.rectangle(200, 380, 250, 50, 0x27ae60);
    rankBtn.setStrokeStyle(3, 0xffffff);
    this.add.text(200, 380, '🏆 전적 보기', {
      fontSize: '20px',
      color: '#ffffff',
      fontStyle: 'bold',
    }).setOrigin(0.5);
    rankBtn.setInteractive({ useHandCursor: true });
    rankBtn.on('pointerover', () => rankBtn.setAlpha(0.8));
    rankBtn.on('pointerout', () => rankBtn.setAlpha(1));
    rankBtn.on('pointerdown', () => this.navigateAway('BattleLeaderboardScene'));

    // 메인 메뉴 텍스트 링크
    const menuLink = this.add.text(200, 450, '메인 메뉴', {
      fontSize: '16px',
      color: '#aaaaaa',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5).setInteractive({ useHandCursor: true });
    menuLink.on('pointerover', () => menuLink.setColor('#ffffff'));
    menuLink.on('pointerout', () => menuLink.setColor('#aaaaaa'));
    menuLink.on('pointerdown', () => this.navigateAway('ModeSelectScene'));

    // 전적 제출 (랭크전 + 친선전 모두)
    if (!this.resultSubmitted) {
      this.resultSubmitted = true;
      submitBattleResult(this.result, this.opponentId, this.isRanked)
        .then((res) => {
          // 랭크 캐시 갱신 (BattleMatchScene에서 즉시 표시용)
          setCachedMyRating(res.ratingPoints, res.rank);
          if (this.isRanked) this.showRpResult(res);
        })
        .catch((err) => {
          console.warn('Battle result submit failed:', err);
          if (this.tierText?.active) this.tierText.setText('전적 기록 실패');
        });
    }

    // 재도전 채널 연결 (친선전만 — 랭크전은 재대전 없음)
    if (this.roomCode && !this.isRanked) {
      this.initRematchChannel();
    }
  }

  /** 제출 응답 수신 후 RP/티어 UI 업데이트 */
  private showRpResult(res: SubmitBattleResultResponse) {
    if (!this.tierText?.active || !this.rpDeltaText?.active) return;

    const oldTierIdx = getTierIndex(res.previousRp);
    const newTierIdx = getTierIndex(res.ratingPoints);
    const newTier = getBattleTier(res.ratingPoints);

    // 기존 티어 이미지 정리
    this.tierIconImg?.destroy();
    this.tierIconImg = undefined;
    this.tierUpgradeOldImg?.destroy();
    this.tierUpgradeOldImg = undefined;
    this.tierArrowText?.destroy();
    this.tierArrowText = undefined;

    if (newTierIdx > oldTierIdx) {
      const oldTier = getBattleTier(res.previousRp);
      // 티어 승급: 구 티어(작게) → 신 티어(크게) 나란히 표시
      this.tierUpgradeOldImg = this.add.image(145, 126, oldTier.imgKey).setDisplaySize(32, 32);
      this.tierArrowText = this.add.text(200, 126, '→', {
        fontSize: '22px', color: '#FFD700', fontStyle: 'bold',
        stroke: '#000', strokeThickness: 4,
      }).setOrigin(0.5);
      this.tierIconImg = this.add.image(255, 126, newTier.imgKey).setDisplaySize(40, 40);
      this.tierText.setText(`${oldTier.name}  →  ${newTier.name}`);
      this.tierText.setColor('#FFD700');
    } else {
      this.tierIconImg = this.add.image(200, 124, newTier.imgKey).setDisplaySize(48, 48);
      this.tierText.setText(`${newTier.name}  |  ${res.ratingPoints} RP`);
      this.tierText.setColor('#cccccc');
    }

    const deltaStr = res.pointDelta >= 0 ? `+${res.pointDelta} RP` : `${res.pointDelta} RP`;
    this.rpDeltaText.setText(deltaStr);
    this.rpDeltaText.setColor(res.pointDelta >= 0 ? '#00ff88' : '#ff4444');

    if (this.currentRpText?.active) {
      this.currentRpText.setText(`현재 ${res.ratingPoints} RP`);
    }
  }

  // ─── 재도전 채널 ────────────────────────────────────────────────

  private async initRematchChannel() {
    this.rematchChannel = new BattleChannel();
    this.rematchChannel.joinResult(this.roomCode, this.userId);

    // subscribe 전에 리스너 등록
    this.rematchChannel.onEvent(BattleEvent.REMATCH_REQUEST, () => {
      this.onOpponentRematchRequest();
    });

    // RESULT_LEAVE: 상대가 의도적으로 내비게이션 시 즉시 알림 (Broadcast 기반)
    this.rematchChannel.onEvent(BattleEvent.RESULT_LEAVE, () => {
      this.onOpponentLeft();
    });

    // Presence leave: 브라우저 종료 등 예기치 않은 이탈 fallback
    this.rematchChannel.onPresenceLeave(() => {
      this.onOpponentLeft();
    });

    await this.rematchChannel.subscribe();
  }

  /** 재대전 버튼 클릭 */
  private handleRematchClick() {
    if (this.myRematchRequested || this.rematchTransitioning) return;
    this.myRematchRequested = true;

    // 버튼 → 대기 상태
    this.rematchBtn.setFillStyle(0x555555);
    this.rematchBtn.removeInteractive();
    this.rematchBtnLabel.setText('⏳ 상대 대기 중...');

    // 상대에게 재도전 의사 전송
    if (this.rematchChannel) {
      this.rematchChannel.sendRematchRequest();
    }

    // 상대도 이미 요청해놨으면 바로 전환
    this.checkBothRematch();
  }

  /** 상대가 재도전 요청을 보냈을 때 */
  private onOpponentRematchRequest() {
    if (this.rematchTransitioning) return;
    this.opponentRematchRequested = true;

    // 내가 아직 안 눌렀다면 → 강조 알림
    if (!this.myRematchRequested) {
      if (this.rematchStatusText?.active) {
        this.rematchStatusText.setText('⚔️ 상대가 재도전을 원합니다!');
        this.rematchStatusText.setColor('#FFD700');
      }
      // 버튼 펄스 애니메이션
      this.tweens.add({
        targets: this.rematchBtn,
        scaleX: 1.06,
        scaleY: 1.06,
        duration: 280,
        yoyo: true,
        repeat: -1,
      });
    }

    this.checkBothRematch();
  }

  /** 상대가 채널에서 이탈했을 때 (RESULT_LEAVE broadcast + Presence leave 양쪽에서 호출될 수 있음) */
  private onOpponentLeft() {
    if (this.rematchTransitioning || this.opponentRematchRequested || this.opponentLeftHandled) return;
    this.opponentLeftHandled = true;

    if (this.rematchStatusText?.active) {
      this.rematchStatusText.setText('😢 상대가 나갔습니다');
      this.rematchStatusText.setColor('#ff6666');
    }

    // 재대전 버튼 비활성화
    this.tweens.killTweensOf(this.rematchBtn);
    this.rematchBtn.setFillStyle(0x333333);
    this.rematchBtn.removeInteractive();
    if (!this.myRematchRequested) {
      this.rematchBtnLabel.setText('재도전 불가');
    }
  }

  /** 양쪽 모두 재도전 의사 확인 시 BattleMatchScene으로 전환 */
  private checkBothRematch() {
    if (!this.myRematchRequested || !this.opponentRematchRequested) return;
    if (this.rematchTransitioning) return;
    this.rematchTransitioning = true;

    this.tweens.killTweensOf(this.rematchBtn);

    if (this.rematchStatusText?.active) {
      this.rematchStatusText.setText('🔄 재대전 시작!');
      this.rematchStatusText.setColor('#00ff88');
    }

    // 호스트 결정: userId 사전순 비교 (양쪽에서 동일하게 계산)
    const isHost = this.userId < this.opponentId;

    this.time.delayedCall(700, () => {
      if (this.rematchChannel) {
        this.rematchChannel.destroyImmediate();
        this.rematchChannel = null;
      }
      this.scene.start('BattleMatchScene', {
        autoRematch: { code: this.roomCode, isHost, userId: this.userId },
      });
    });
  }

  /**
   * 재도전 외 내비게이션 시 상대에게 이탈 broadcast 전송 후 씬 전환
   * Presence leave는 WebSocket 타임아웃에 의존하므로 신뢰성 낮음 →
   * 의도적 이탈은 Broadcast로 즉시 알림
   */
  private navigateAway(targetScene: string) {
    if (this.rematchChannel) {
      this.rematchChannel.sendResultLeave();
      this.rematchChannel.destroyImmediate();
      this.rematchChannel = null;
    }
    this.scene.start(targetScene);
  }

  shutdown() {
    if (this.rematchChannel) {
      this.rematchChannel.destroyImmediate();
      this.rematchChannel = null;
    }
  }
}

