    this.ui(this.add.text(200, 400, '캐릭터를 확인하고 준비하세요', {
      fontSize: '13px', color: '#bbbbbb', stroke: '#000', strokeThickness: 2,
    }).setOrigin(0.5));

    const readyBtn = this.ui(this.add.rectangle(200, 440, 270, 64, 0x1e8449));
