import type Phaser from 'phaser';
import { Difficulty, Difficulty as DifficultyEnum } from '../types/GameMode';
import { getLeaderboard, type LeaderboardEntry } from '../utils/leaderboard';
import { getPendingRewards, sumPending, claimSeasonReward } from '../utils/seasonReward';
import BaseScene from './BaseScene';

export default class LeaderboardScene extends BaseScene {
  private selectedDifficulty: Difficulty = DifficultyEnum.NORMAL;
  private leaderboardData: LeaderboardEntry[] = [];
  private leaderboardTexts: Phaser.GameObjects.Text[] = [];
  private loadingText?: Phaser.GameObjects.Text;
  private errorText?: Phaser.GameObjects.Text;
  private seasonBadge?: Phaser.GameObjects.Text;
  private currentRequestId: number = 0; // 요청 추적용 ID
  private difficultyButtons = new Map<Difficulty, Phaser.GameObjects.Rectangle>();

  constructor() {
    super('LeaderboardScene');
  }

  init() {
    const last = localStorage.getItem('lastPlayedDifficulty') as Difficulty | null;
    if (last) {
      this.selectedDifficulty = last;
    }
  }

  preload() {
    // 배경 이미지 로드 (캐시 확인으로 중복 로딩 방지)
    if (!this.textures.exists('background2')) {
      this.load.image('background2', 'assets/backgrounds/background2.webp');
    }
  }

  create() {
    super.create();

    // 배경 이미지 추가
    const background = this.add.image(200, 300, 'background2');
    background.setDisplaySize(400, 600);

    // 타이틀
    this.add.text(200, 40, '🏆 랭킹보드 🏆', {
      fontSize: '28px',
      color: '#fff',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 5
    }).setOrigin(0.5);

    // 시즌 배지 (데이터 로드 후 showSeasonBadge로 채워짐)
    this.seasonBadge = this.add.text(200, 68, '', {
      fontSize: '13px',
      color: '#88ccff',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5);

    // 난이도 선택 버튼들 (y좌표 10px 아래로)
    this.createDifficultyButtons();

    // 랭킹 표시 영역 (초기 로딩)
    this.loadingText = this.add.text(200, 300, '로딩 중...', {
      fontSize: '20px',
      color: '#fff',
      stroke: '#000',
      strokeThickness: 3
    }).setOrigin(0.5);

    // 뒤로가기 버튼
    this.createBackButton();

    // 보상 수령 버튼 (pending 있을 때만 표시)
    this.createClaimButton();

    // 초기 데이터 로드 + 보상 체크 병렬
    this.loadLeaderboard();
    this.checkPendingRewards();
  }

  private createDifficultyButtons() {
    this.difficultyButtons.forEach(btn => btn.destroy());
    this.difficultyButtons.clear();

    const difficulties: Difficulty[] = [
      DifficultyEnum.NORMAL,
      DifficultyEnum.HARD,
      DifficultyEnum.EXTREME,
      DifficultyEnum.PHYSICAL
    ];

    const buttonWidth = 70;
    const spacing = 85;
    const startX = 200 - (spacing * 1.5);
    const y = 105;

    difficulties.forEach((difficulty, index) => {
      const x = startX + (index * spacing);
      const isSelected = difficulty === this.selectedDifficulty;

      const button = this.add.rectangle(
        x,
        y,
        buttonWidth,
        35,
        isSelected ? 0xffff99 : 0xffffff,
        1
      );
      button.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);

      this.add.text(x, y, difficulty, {
        fontSize: '12px',
        color: '#000',
        fontStyle: 'bold'
      }).setOrigin(0.5);

      this.difficultyButtons.set(difficulty, button);
      button.setInteractive({ useHandCursor: true });

      button.on('pointerover', () => {
        if (difficulty !== this.selectedDifficulty) {
          button.setFillStyle(0xffffcc);
        }
      });

      button.on('pointerout', () => {
        if (difficulty !== this.selectedDifficulty) {
          button.setFillStyle(0xffffff);
        }
      });

      button.on('pointerdown', () => {
        this.selectDifficulty(difficulty);
      });
    });
  }

  private selectDifficulty(difficulty: Difficulty) {
    // 같은 난이도면 무시
    if (this.selectedDifficulty === difficulty) {
      return;
    }

    this.selectedDifficulty = difficulty;

    // 모든 버튼 스타일 재설정
    this.difficultyButtons.forEach((btn, diff) => {
      const isSelected = diff === difficulty;
      btn.setFillStyle(isSelected ? 0xffff99 : 0xffffff);
      btn.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
    });

    // 새로운 난이도 데이터 로드
    this.loadLeaderboard();
  }

  private async loadLeaderboard() {
    // 요청 ID 증가 (새로운 요청 시작)
    this.currentRequestId++;
    const requestId = this.currentRequestId;

    // 기존 랭킹 텍스트 제거
    this.leaderboardTexts.forEach(text => text.destroy());
    this.leaderboardTexts = [];

    if (this.errorText) {
      this.errorText.destroy();
      this.errorText = undefined;
    }

    // 로딩 표시
    if (!this.loadingText) {
      this.loadingText = this.add.text(200, 300, '로딩 중...', {
        fontSize: '20px',
        color: '#fff',
        stroke: '#000',
        strokeThickness: 3
      }).setOrigin(0.5);
    } else {
      this.loadingText.setVisible(true);
    }

    try {
      const response = await getLeaderboard(this.selectedDifficulty, 10);

      // 응답이 도착했을 때 최신 요청인지 확인
      if (requestId !== this.currentRequestId) {
        // 이미 새로운 요청이 시작됨 - 이 응답은 무시
        return;
      }

      this.leaderboardData = response.leaderboard;

      if (this.loadingText) {
        this.loadingText.setVisible(false);
      }

      this.showSeasonBadge(this.seasonBadge!, response.seasonName, response.seasonEndsAt ?? null);
      this.displayLeaderboard();
    } catch (error) {
      // 에러가 발생했을 때도 최신 요청인지 확인
      if (requestId !== this.currentRequestId) {
        // 이미 새로운 요청이 시작됨 - 이 에러는 무시
        return;
      }

      console.error('Failed to load leaderboard:', error);

      if (this.loadingText) {
        this.loadingText.setVisible(false);
      }

      this.errorText = this.add.text(200, 300, '랭킹을 불러올 수 없습니다\n\n나중에 다시 시도해주세요', {
        fontSize: '16px',
        color: '#ff6666',
        stroke: '#000',
        strokeThickness: 3,
        align: 'center'
      }).setOrigin(0.5);
    }
  }

  private displayLeaderboard() {
    const startY = 150;
    const lineHeight = 35;

    // 헤더
    const headerText = this.add.text(200, startY, '순위    이름      점수', {
      fontSize: '16px',
      color: '#ffff00',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 4
    }).setOrigin(0.5);
    this.leaderboardTexts.push(headerText);

    // 랭킹 데이터 표시
    if (this.leaderboardData.length === 0) {
      const noDataText = this.add.text(200, startY + 50, '아직 랭킹이 없습니다\n\n첫 번째 플레이어가 되어보세요!', {
        fontSize: '18px',
        color: '#ccc',
        stroke: '#000',
        strokeThickness: 3,
        align: 'center'
      }).setOrigin(0.5);
      this.leaderboardTexts.push(noDataText);
      return;
    }

    this.leaderboardData.forEach((entry, index) => {
      const y = startY + 30 + (index * lineHeight);

      // 순위별 색상
      let color = '#ffffff';
      if (entry.rank === 1) color = '#FFD700'; // 금색
      else if (entry.rank === 2) color = '#C0C0C0'; // 은색
      else if (entry.rank === 3) color = '#CD7F32'; // 동색


      const rankText = `${entry.rank}`.padEnd(8, ' ');
      const nameText = entry.userName.padEnd(8, ' ');
      const scoreText = entry.score.toString().padStart(6, ' ');

      const text = this.add.text(
        200,
        y,
        `${rankText}${nameText}${scoreText}`,
        {
          fontSize: '16px',
          color: color,
          fontFamily: 'monospace',
          stroke: '#000',
          strokeThickness: 3
        }
      ).setOrigin(0.5);

      this.leaderboardTexts.push(text);
    });
  }

  private createClaimButton() {
    // 초기에는 숨김 — checkPendingRewards에서 보상 있으면 표시
    this.claimBtnBg = this.add.rectangle(200, 520, 300, 40, 0x1a5c1a)
      .setStrokeStyle(2, 0x44ee44)
      .setVisible(false);
    this.claimBtnTxt = this.add.text(200, 520, '', {
      fontSize: '15px', color: '#88ff88', fontStyle: 'bold',
      stroke: '#000', strokeThickness: 3,
    }).setOrigin(0.5).setVisible(false);
  }

  private async checkPendingRewards() {
    try {
      const rewards = await getPendingRewards();
      const total = sumPending(rewards, 'classic');
      if (total <= 0 || !this.claimBtnBg || !this.claimBtnTxt) return;

      this.claimBtnTxt.setText(`🎁 클래식 시즌 보상 수령 (+${total} SKOR)`);
      this.claimBtnBg.setVisible(true).setInteractive({ useHandCursor: true });
      this.claimBtnTxt.setVisible(true);

      this.claimBtnBg.on('pointerover', () => this.claimBtnBg?.setFillStyle(0x257a25));
      this.claimBtnBg.on('pointerout', () => this.claimBtnBg?.setFillStyle(0x1a5c1a));
      this.claimBtnBg.on('pointerdown', () => this.handleClaim());
    } catch {
      // 비크리티컬 — 보상 버튼 없으면 그냥 숨김 유지
    }
  }

  private async handleClaim() {
    if (!this.claimBtnBg || !this.claimBtnTxt) return;

    // 버튼 비활성화 (중복 클릭 방지)
    this.claimBtnBg.disableInteractive();
    this.claimBtnTxt.setText('수령 중...');

    try {
      const result = await claimSeasonReward('classic');
      if (result.claimedAmount > 0) {
        this.claimBtnTxt.setText(`✅ +${result.claimedAmount} SKOR 수령 완료!`).setColor('#ffffff');
        this.claimBtnBg.setFillStyle(0x555555).setStrokeStyle(2, 0x888888);
        // 2초 후 버튼 숨김
        this.time.delayedCall(2000, () => {
          this.claimBtnBg?.setVisible(false);
          this.claimBtnTxt?.setVisible(false);
        });
      } else {
        this.claimBtnBg.setVisible(false);
        this.claimBtnTxt.setVisible(false);
      }
    } catch {
      this.claimBtnTxt.setText('수령 실패 — 다시 시도해주세요').setColor('#ff6666');
      this.claimBtnBg.setInteractive({ useHandCursor: true });
    }
  }

  private createBackButton() {
    const button = this.add.rectangle(200, 560, 150, 40, 0xffffff, 1);
    button.setStrokeStyle(3, 0x000000);

    const text = this.add.text(200, 560, '← 뒤로가기', {
      fontSize: '18px',
      color: '#000',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    button.setInteractive({ useHandCursor: true });

    const elements = [button, text];
    elements.forEach(element => {
      element.on('pointerover', () => {
        button.setFillStyle(0xffff99);
      });

      element.on('pointerout', () => {
        button.setFillStyle(0xffffff);
      });

      element.on('pointerdown', () => {
        this.scene.start('ModeSelectScene');
      });
    });
  }
}

