import { supabase } from './supabase';

// 모듈 레벨 캐시 — 씬 간 이동 시 중복 fetch 방지 (TTL: 60초)
let _cachedRewards: SeasonReward[] | null = null;
let _cacheTs = 0;
const _CACHE_TTL = 60_000;

export interface SeasonReward {
  seasonId: number;
  rewardType: string;   // 'classic_normal' | 'classic_hard' | 'classic_extreme' | 'classic_physical' | 'battle'
  skorAmount: number;
  rank: number;
}

export interface ClaimResult {
  success: boolean;
  claimedAmount: number;
  newBalance: number;
  details: Array<{ seasonId: number; rewardType: string; skor: number; rank: number }>;
}

/** 미수령 시즌 보상 조회 (RLS: 자신의 것만). 60초 모듈 캐시 적용. */
export async function getPendingRewards(): Promise<SeasonReward[]> {
  if (_cachedRewards !== null && Date.now() - _cacheTs < _CACHE_TTL) {
    return _cachedRewards;
  }

  const { data, error } = await supabase
    .from('season_rewards')
    .select('season_id, reward_type, skor_amount, rank')
    .is('claimed_at', null);

  if (error || !data) return [];

  _cachedRewards = data.map((r: { season_id: number; reward_type: string; skor_amount: number; rank: number }) => ({
    seasonId: r.season_id,
    rewardType: r.reward_type,
    skorAmount: r.skor_amount,
    rank: r.rank,
  }));
  _cacheTs = Date.now();
  return _cachedRewards;
}

/** 수령 후 캐시 무효화 */
export function invalidatePendingRewardsCache(): void {
  _cachedRewards = null;
}

/** 카테고리별 미수령 보상 합산 금액 */
export function sumPending(rewards: SeasonReward[], category: 'classic' | 'battle'): number {
  return rewards
    .filter(r => category === 'battle' ? r.rewardType === 'battle' : r.rewardType.startsWith('classic_'))
    .reduce((sum, r) => sum + r.skorAmount, 0);
}

/** 시즌 보상 수령 */
export async function claimSeasonReward(category: 'classic' | 'battle'): Promise<ClaimResult> {
  const { data, error } = await supabase.functions.invoke('claim-season-reward', {
    body: { category },
  });

  if (error) {
    throw new Error(error.message || 'Failed to claim season reward');
  }

  return data as ClaimResult;
}

